import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import '../css/ProjectPage.css';

export default function ProjectPage() {
    const navigate = useNavigate();
    const [name, setName] = useState('');
    const [description, setDescription] = useState('');

    const handleBack = () => navigate(-1);
    const handleCreate = (e) => {
        e.preventDefault();
        // TODO: API call to create project
        console.log({ name, description });
        // 이후 생성 완료 시 다른 페이지로 이동하거나 초기화
    };

    return (
        <div className="projectpage-container">
            <header className="projectpage-header">
                <button className="back-btn" onClick={handleBack}>← 뒤로</button>
                <h2>새 프로젝트 생성</h2>
            </header>

            <form className="project-form" onSubmit={handleCreate}>
                <label>
                    프로젝트 이름
                    <input
                        type="text"
                        value={name}
                        onChange={e => setName(e.target.value)}
                        placeholder="프로젝트 이름을 입력하세요"
                        required
                    />
                </label>

                <label>
                    설명
                    <textarea
                        value={description}
                        onChange={e => setDescription(e.target.value)}
                        placeholder="프로젝트 설명을 입력하세요"
                    />
                </label>

                <button type="submit" className="create-btn">프로젝트 생성</button>
            </form>
        </div>
    );
}
